INSERT INTO interpretation_templates (condition_key, condition_value, category, title, summary, content, weight, is_active) VALUES
('element_tag', 'wood_excess', 'general', '목 과다 · 총운', '새로운 시작과 성장에 대한 욕구가 본능에 가깝습니다. 아이디어는 끊임없이 넘치지만, 하나를 끝까지 완성하는 집중력을 키우는 것이 평생의 과제입니다.', '목(木) 기운이 강한 당신은 생명력과 창의성이 풍부하고, 언제나 새로운 것을 시작하고 싶은 충동이 있습니다. 아이디어가 끊임없이 샘솟아 주변 사람들을 자극하는 역할을 하지만, 목이 지나치면 뿌리 없는 나무처럼 흔들릴 수 있습니다. 여러 일을 동시에 시작하다 어느 것 하나 마무리 짓지 못하는 경향이 가장 큰 과제입니다. 올해는 새로운 시작보다 진행 중인 것을 완성하는 데 집중하는 것이 가장 현명한 선택입니다.', 80, true),
('element_tag', 'wood_excess', 'career', '목 과다 · 직업운', '창의적인 아이디어로 주목받을 수 있지만, 실행력과 마무리 능력을 함께 키워야 진짜 성과가 따라옵니다.', '목 기운이 강한 직업운은 기획, 창업, 교육, 예술 분야에서 빛을 발합니다. 아이디어를 내는 능력이 뛰어나고 새로운 프로젝트를 이끄는 힘이 있어 조직에서 없어서는 안 될 존재가 됩니다. 단, 목이 과다하면 한 가지 일에 집중하지 못하고 여러 방향으로 에너지가 분산되어 성과가 흐릿해지는 경우가 있습니다. 믿을 수 있는 동료와 함께 역할을 명확히 분담하고, 마감 기한을 스스로 설정하는 습관이 당신의 강점을 배가시킵니다.', 80, true),
('element_tag', 'wood_excess', 'love', '목 과다 · 애정운', '낭만적이고 이상적인 사랑을 꿈꾸지만, 설렘이 식을 때도 관계를 지속하는 꾸준함이 진짜 사랑을 만듭니다.', '목 기운이 강한 당신은 연애에서도 늘 새로운 설렘을 추구합니다. 처음 만나는 순간의 두근거림을 사랑하고, 상대방에게 창의적이고 로맨틱한 순간을 만들어주는 데 탁월합니다. 그러나 목이 과다하면 처음의 감정이 식었을 때 새로운 것을 찾고 싶어지는 경향이 생겨, 장기적인 관계를 유지하는 데 의식적인 노력이 필요합니다. 지금 있는 관계 안에서 새로운 면을 발견하고 함께 성장하는 방향이 가장 풍성한 사랑을 만들어냅니다.', 80, true),
('element_tag', 'wood_excess', 'wealth', '목 과다 · 재물운', '새로운 수익 기회를 포착하는 능력이 뛰어납니다. 단 너무 많은 곳에 투자하면 정작 중요한 것을 놓치니 집중이 필요합니다.', '목 기운이 강한 재물운은 다양한 방면에서 새로운 수익 통로가 열리는 상태입니다. 사업 아이디어, 부업, 투자 기회 등 여러 가능성이 보이는 시기이며 이 중 하나를 잘 선택하면 큰 수확을 거둘 수 있습니다. 그러나 목이 과다하면 너무 많은 곳에 동시에 투자하다가 모두 어중간하게 끝나는 경우가 생깁니다. 한 가지 재물 경로에 집중하고, 계획 없는 충동 지출을 줄이면 연말에 의미 있는 결실을 맺을 수 있습니다.', 80, true),
('element_tag', 'wood_excess', 'health', '목 과다 · 건강운', '간과 눈 건강에 특별히 신경 쓰고, 신경이 예민해지기 전에 미리 스트레스를 해소하는 습관을 만드세요.', '목(木)은 한의학에서 간(肝)과 눈, 근육, 신경계와 연결됩니다. 목 기운이 과다하면 간에 열이 쌓이거나 눈의 피로, 두통, 근육 긴장이 나타날 수 있습니다. 신경이 예민해지고 사소한 일에도 쉽게 스트레스를 받는 경향이 있으니 정기적인 휴식과 이완이 무엇보다 중요합니다. 녹색 채소와 신맛 나는 음식이 간 건강에 도움이 되며, 규칙적인 스트레칭과 야외 걷기로 목 기운의 과부하를 자연스럽게 해소해주세요.', 80, true),
('element_tag', 'wood_balanced', 'general', '목 균형 · 총운', '성장과 안정의 에너지가 자연스럽게 균형을 이루는 기질을 타고났습니다. 시작과 마무리를 모두 잘 해내는 것이 이 기질의 가장 큰 강점입니다.', '목(木) 기운이 균형 잡힌 당신은 창의성과 실행력, 시작과 마무리의 조화를 자연스럽게 이루고 있습니다. 봄의 생명력처럼 적절한 성장 에너지가 삶에 활력을 더하고, 무리하지 않으면서도 꾸준히 앞으로 나아갑니다. 이 균형 상태는 큰 노력 없이도 일이 잘 풀리는 좋은 기반이 되어줍니다. 새로운 시도와 기존의 것을 지키는 균형을 의식적으로 유지하면서 자신이 원하는 방향으로 성장해나가세요.', 60, true),
('element_tag', 'wood_balanced', 'career', '목 균형 · 직업운', '창의력과 실행력이 자연스럽게 조화를 이루는 직업 기질을 가졌습니다. 아이디어를 현실로 옮기는 능력이 어떤 직업에서든 강점이 됩니다.', '목 기운이 균형을 이룬 직업운은 창의적인 아이디어를 실제로 구현하는 힘이 안정적인 상태입니다. 새로운 프로젝트를 시작하고 마무리하는 사이클이 원활하게 돌아가며, 동료들과의 협업에서도 좋은 시너지를 냅니다. 이 시기에 새로운 기술을 배우거나 업무 영역을 확장하면 장기적으로 큰 자산이 됩니다. 지금의 균형 상태를 자신감의 발판으로 삼아 조금 더 도전적인 목표를 향해 나아가도 좋습니다.', 60, true),
('element_tag', 'wood_balanced', 'love', '목 균형 · 애정운', '설렘과 안정을 동시에 원하는 연애 기질을 타고났습니다. 새로움과 편안함을 함께 나눌 수 있는 파트너와 가장 잘 맞습니다.', '목 기운이 균형 잡힌 애정운은 이상과 현실 사이에서 성숙하게 균형을 잡고 있는 상태입니다. 새로운 감정의 흥분도 소중히 여기면서도 일상 속에서 파트너와 쌓아가는 소소한 행복도 함께 즐길 수 있습니다. 싱글이라면 자연스럽고 건강한 인연이 만들어지기 좋은 시기이니 열린 마음을 유지하세요. 이미 관계 중이라면 서로의 성장을 응원하는 파트너십이 더욱 단단해지는 시기입니다.', 60, true),
('element_tag', 'wood_balanced', 'wealth', '목 균형 · 재물운', '안정적이면서도 꾸준히 성장하는 재물 흐름입니다. 계획적인 투자와 꾸준한 저축이 좋은 결실을 맺습니다.', '목 기운이 균형을 이룬 재물운은 새로운 수익 기회와 안정적인 자산 관리 사이에서 균형을 유지하는 상태입니다. 갑작스러운 큰 변화보다 꾸준하고 계획적인 방식으로 재물을 늘려가는 것이 이 시기에 가장 잘 맞는 접근법입니다. 소액으로 새로운 투자를 조심스럽게 시험해보거나 장기 저축 계획을 구체화하는 것도 좋습니다. 충동적인 지출만 피한다면 연말에 기분 좋은 결산을 할 수 있습니다.', 60, true),
('element_tag', 'wood_balanced', 'health', '목 균형 · 건강운', '건강 에너지가 균형을 이루고 있는 좋은 상태입니다. 지금의 생활 습관을 잘 유지하는 것이 가장 중요합니다.', '목 기운이 균형을 이룬 건강운은 간, 눈, 근육 등 목과 관련된 신체 기관들이 안정적으로 작동하고 있는 상태입니다. 지금의 건강 습관이 몸에 잘 맞고 있다는 신호이니 크게 바꾸려 하기보다 꾸준히 유지하는 것이 핵심입니다. 규칙적인 수면, 적당한 운동, 스트레스 관리의 균형을 지켜나가세요. 봄철에는 야외 활동을 조금씩 늘리고 신선한 채소 섭취를 늘리면 이 균형을 더욱 탄탄하게 유지할 수 있습니다.', 60, true),
('element_tag', 'wood_deficient', 'general', '목 부족 · 총운', '새로운 시작과 변화를 만드는 에너지가 상대적으로 약한 기질입니다. 작은 것부터 하나씩 시도하는 꾸준함이 이 기질의 성장 방식입니다.', '목(木) 기운이 부족한 당신은 새로운 것을 시작하거나 변화를 만드는 데 평소보다 어려움을 느낄 수 있습니다. 마치 겨울이 길어진 것처럼 봄의 생명력이 아직 깨어나지 않은 상태로, 무언가를 시작하려 해도 이유 없이 에너지가 부족하게 느껴집니다. 이 시기에는 큰 변화를 억지로 만들려 하기보다 작은 것부터 하나씩 시도하는 것이 현명합니다. 초록색 자연과 가까이하고, 성장에 대한 긍정적인 마인드를 의식적으로 키워나가면 자연스럽게 기운이 회복됩니다.', 80, true),
('element_tag', 'wood_deficient', 'career', '목 부족 · 직업운', '창의적 발상이 필요한 업무에서 어려움을 느낄 수 있습니다. 안정적인 루틴 업무에서 강점을 발휘하며 역량을 쌓으세요.', '목 기운이 부족한 직업운은 창의적인 기획이나 새로운 프로젝트를 시작하는 데 에너지가 약한 상태입니다. 반면 주어진 일을 꾸준히 완수하고 안정적으로 업무를 처리하는 능력에서는 오히려 강점을 보일 수 있습니다. 이 시기에는 혁신보다 기존의 것을 개선하고 완성도를 높이는 데 집중하는 것이 현명합니다. 독서나 온라인 강의를 통해 꾸준히 새로운 지식을 쌓으면 목 기운을 보충하면서 직업 역량도 함께 키울 수 있습니다.', 80, true),
('element_tag', 'wood_deficient', 'love', '목 부족 · 애정운', '관계를 먼저 시작하거나 감정을 표현하는 데 소극적일 수 있습니다. 작은 용기 하나가 큰 변화를 만들어냅니다.', '목 기운이 부족한 애정운은 연애에서 먼저 시작하거나 감정을 적극적으로 표현하는 데 어려움을 느끼는 상태입니다. 관심 있는 사람에게도 선뜻 다가가지 못하거나, 좋은 인연을 만날 기회가 와도 망설이다 놓치는 경우가 있을 수 있습니다. 이 시기에는 소심함보다 작은 용기를 내는 것을 추천합니다. 이미 관계 중이라면 상대방이 원하는 새로운 경험이나 변화를 제안해보는 것이 관계에 신선한 활력을 불어넣습니다.', 80, true),
('element_tag', 'wood_deficient', 'wealth', '목 부족 · 재물운', '새로운 수익 기회를 포착하는 감각이 약한 시기입니다. 안정적인 저축과 지출 관리가 최선의 재물 전략입니다.', '목 기운이 부족한 재물운은 새로운 투자나 사업 기회를 포착하고 시작하는 것이 쉽지 않은 상태입니다. 좋은 투자 정보를 들어도 결정을 미루다 타이밍을 놓치거나, 처음 시작하는 것 자체에 큰 부담을 느낄 수 있습니다. 이 시기에는 새로운 재물 창출보다 현재 수입을 꼼꼼히 관리하고 불필요한 지출을 줄이는 것이 가장 현명합니다. 소액 적립식 저축이나 안정적인 금융 상품으로 탄탄한 기초를 다지는 데 집중하세요.', 80, true),
('element_tag', 'wood_deficient', 'health', '목 부족 · 건강운', '간 기능과 눈 건강에 주의가 필요합니다. 충분한 휴식과 야외 활동으로 생명 에너지를 보충해주세요.', '목 기운이 부족하면 간 기능이 약해지거나 눈의 피로, 근육 경직, 면역력 저하 등이 나타날 수 있습니다. 피로 회복이 느리고 쉽게 지치는 경향이 있으니 충분한 수면과 규칙적인 휴식이 무엇보다 중요합니다. 초록색 채소와 신맛 나는 음식을 꾸준히 섭취하고, 산이나 공원 등 자연과 가까이하는 시간을 의도적으로 늘려보세요. 무리하지 않는 가벼운 스트레칭과 유산소 운동이 목 기운을 자연스럽게 보충하는 데 도움이 됩니다.', 80, true),
('element_tag', 'fire_excess', 'general', '화 과다 · 총운', '열정과 에너지가 넘치는 시기입니다. 이 불꽃 같은 에너지를 한 방향으로 집중하면 놀라운 결과를 만들 수 있습니다.', '화(火) 기운이 강한 당신은 열정과 추진력, 표현력이 넘칩니다. 어떤 일이든 빠르게 결정하고 즉각 행동에 나서는 힘이 있어 주변에 활력을 불어넣는 존재입니다. 그러나 화가 과다하면 불꽃이 타오르다 갑자기 꺼지듯이 에너지가 빠르게 소진되거나, 충동적인 결정으로 후회하는 일이 생길 수 있습니다. 이 강한 에너지를 한 방향으로 집중하고, 큰 결정 전에 잠시 숨을 고르는 습관이 당신의 화 기운을 가장 빛나게 활용하는 방법입니다.', 80, true),
('element_tag', 'fire_excess', 'career', '화 과다 · 직업운', '추진력과 리더십이 뛰어나 주변을 이끄는 힘이 있습니다. 다만 지속력을 의식적으로 관리해야 장기 성과가 따라옵니다.', '화 기운이 강한 직업운은 영업, 마케팅, 엔터테인먼트, 리더십이 필요한 분야에서 특히 강점을 발휘합니다. 빠른 판단력과 뜨거운 추진력으로 단기간에 눈에 띄는 성과를 만들어내는 능력이 있습니다. 그러나 화가 과다하면 초반에 너무 많은 에너지를 쏟아붓다가 중반 이후 급격히 지치거나, 감정적인 결정으로 관계가 틀어지는 경우가 생깁니다. 중요한 결정 전에 하루 이상 생각하는 습관과, 장기 계획을 세워 에너지를 분산하는 연습이 필요합니다.', 80, true),
('element_tag', 'fire_excess', 'love', '화 과다 · 애정운', '열정적이고 감정 표현이 풍부해 상대방을 압도하는 매력이 있습니다. 상대방의 페이스도 배려하는 여유가 관계를 오래 가게 합니다.', '화 기운이 강한 당신의 연애는 뜨겁고 강렬합니다. 좋아하는 감정을 숨기지 않고 표현하며, 상대방에게 잊을 수 없는 순간들을 선사하는 데 탁월합니다. 그러나 화가 과다하면 지나치게 빠른 속도로 관계를 밀어붙이거나, 작은 오해에도 감정이 크게 폭발하는 경향이 있습니다. 상대방의 페이스와 감정을 배려하고, 갈등 상황에서 잠깐 자리를 피해 냉각 시간을 갖는 것이 이 강한 화 기운을 아름다운 사랑으로 만드는 비결입니다.', 80, true),
('element_tag', 'fire_excess', 'wealth', '화 과다 · 재물운', '빠른 수익 기회를 포착하는 능력이 있지만, 충동적인 소비와 투자가 화를 부를 수 있으니 반드시 한 템포 늦추세요.', '화 기운이 강한 재물운은 기회를 빠르게 포착하고 과감하게 행동하는 데 유리합니다. 단기적인 수익을 만들어내는 능력이 있고, 직관적으로 좋은 기회를 알아채는 감각이 있습니다. 그러나 화가 과다하면 충동적인 지출이나 검토 없는 투자 결정으로 큰 손실을 입을 위험도 함께 큽니다. 어떤 지출이나 투자든 최소 하루를 기다린 후 결정하는 규칙을 만들고, 비상금은 손대기 어려운 별도 계좌에 분리해두는 것이 필요합니다.', 80, true),
('element_tag', 'fire_excess', 'health', '화 과다 · 건강운', '심장과 혈압 관리가 가장 중요합니다. 과로와 흥분 상태가 지속되지 않도록 의식적으로 쉬어가세요.', '화(火)는 한의학에서 심장(心), 소장, 혈액순환과 깊이 연결됩니다. 화 기운이 과다하면 심장에 부담이 가거나 혈압이 오르고, 불면증이나 가슴 두근거림이 나타날 수 있습니다. 또한 흥분 상태가 지속되어 신체 전반적으로 과부하가 걸리기 쉬우니 의식적으로 속도를 늦추고 쉬는 시간을 만들어야 합니다. 붉은 육류는 줄이고 쓴맛 나는 음식(여주, 쑥 등)이 화 기운을 안정시키는 데 도움이 됩니다. 명상이나 스트레칭을 통한 이완 루틴을 반드시 만드세요.', 80, true),
('element_tag', 'fire_balanced', 'general', '화 균형 · 총운', '열정과 이성이 균형을 이루는 기질을 타고났습니다. 필요한 순간 뜨거운 에너지를 발휘하면서도 과열을 스스로 조절하는 능력이 있습니다.', '화(火) 기운이 균형 잡힌 당신은 열정과 냉정함, 추진력과 인내심이 조화를 이루고 있습니다. 필요한 순간에 뜨거운 에너지를 발휘하되, 지나치게 과열되지 않도록 스스로를 조절하는 능력이 있습니다. 이 균형 잡힌 상태는 중요한 결정을 내릴 때나 대인관계에서 큰 자산이 됩니다. 지금의 이 균형을 믿고 원하는 목표를 향해 꾸준히 에너지를 쏟아보세요.', 60, true),
('element_tag', 'fire_balanced', 'career', '화 균형 · 직업운', '열정과 추진력이 자연스럽게 균형을 이루는 직업 기질입니다. 빠른 추진력을 유지하면서도 지치지 않는 페이스 조절이 타고난 강점입니다.', '화 기운이 균형을 이룬 직업운은 빠른 추진력과 꾸준한 지속력이 동시에 발휘되는 이상적인 상태입니다. 새로운 프로젝트를 시작하는 패기와, 중간에 포기하지 않는 끈기가 함께 있어 어떤 업무도 좋은 결과로 이어집니다. 리더십이 필요한 역할에서 특히 빛을 발하며, 동료들에게도 긍정적인 에너지를 전달합니다. 이 시기에 새로운 도전이나 승진 기회가 온다면 적극적으로 임해도 좋습니다.', 60, true),
('element_tag', 'fire_balanced', 'love', '화 균형 · 애정운', '감정 표현과 절제가 균형을 이루는 성숙한 연애 기질을 가졌습니다. 뜨겁게 사랑하면서도 상대방을 배려하는 능력이 관계를 깊고 오래가게 합니다.', '화 기운이 균형 잡힌 애정운은 뜨거운 감정을 적절하게 표현하면서도 상대방을 배려하는 성숙함이 있는 상태입니다. 필요할 때는 적극적으로 사랑을 표현하고, 갈등 상황에서는 감정을 조절할 줄 아는 균형이 관계를 안정적으로 이끕니다. 싱글이라면 이 균형 잡힌 에너지가 좋은 인연을 끌어당기는 매력이 됩니다. 현재 관계 중이라면 서로를 향한 감정이 더욱 깊어지는 의미 있는 시기입니다.', 60, true),
('element_tag', 'fire_balanced', 'wealth', '화 균형 · 재물운', '적극성과 신중함이 균형을 이뤄 재물운이 안정적입니다. 좋은 기회를 놓치지 않으면서도 리스크도 잘 관리합니다.', '화 기운이 균형을 이룬 재물운은 기회를 포착하는 직관과 신중하게 판단하는 이성이 동시에 작동하는 상태입니다. 좋은 투자 기회에 과감하게 행동하면서도 지나친 위험은 피하는 균형 잡힌 접근이 가능합니다. 이 시기에 꾸준한 저축과 적절한 투자를 병행하면 재물이 안정적으로 늘어나는 것을 체감할 수 있습니다. 재정 계획을 구체적으로 세우기 좋은 시기이니 장기 목표를 정하고 그에 맞는 전략을 수립해보세요.', 60, true),
('element_tag', 'fire_balanced', 'health', '화 균형 · 건강운', '심장과 혈액순환이 안정적인 좋은 상태입니다. 지금의 생활 리듬을 유지하면서 꾸준한 운동 습관을 이어가세요.', '화 기운이 균형을 이룬 건강운은 심장 기능, 혈액순환, 체온 조절 등이 안정적으로 작동하고 있는 상태입니다. 과도한 흥분이나 극심한 피로 없이 일상을 안정적으로 유지하고 있다는 신호입니다. 지금의 운동 습관과 식사 패턴이 몸에 잘 맞고 있으니 크게 바꾸기보다 꾸준히 이어가는 것이 중요합니다. 가벼운 유산소 운동을 꾸준히 하고, 충분한 수분 섭취를 통해 혈액 순환을 원활하게 유지하세요.', 60, true),
('element_tag', 'fire_deficient', 'general', '화 부족 · 총운', '열정과 추진력이 상대적으로 약한 기질입니다. 작은 성공 경험을 쌓아가며 스스로 동기를 만드는 것이 이 기질의 핵심 성장법입니다.', '화(火) 기운이 부족한 당신은 무언가를 향한 열정과 실행 의지가 평소보다 약해진 상태입니다. 무기력하거나 매사에 흥미를 느끼지 못하는 경우가 있으며, 좋은 기회가 와도 선뜻 나서지 못하는 경향이 생깁니다. 이 시기에는 자신을 억지로 채찍질하기보다 작은 성취를 경험하며 스스로에게 에너지를 채워주는 것이 현명합니다. 열정적인 사람들과 어울리고, 좋아하는 활동에 시간을 투자하면 화 기운이 자연스럽게 회복됩니다.', 80, true),
('element_tag', 'fire_deficient', 'career', '화 부족 · 직업운', '실행력과 추진력이 약해 업무 속도가 느려질 수 있습니다. 팀워크와 외부 동기 부여가 이 시기의 핵심 전략입니다.', '화 기운이 부족한 직업운은 업무에서 적극성과 추진력이 약해지는 상태입니다. 해야 할 일을 알면서도 시작하기가 어렵거나, 중요한 상황에서 뒤로 물러서는 경향이 생길 수 있습니다. 이 시기에는 혼자 모든 것을 해결하려 하기보다 에너지 넘치는 동료와 팀으로 일하는 것이 큰 도움이 됩니다. 업무 목표를 작게 쪼개서 매일 작은 성취감을 느끼는 구조를 만들고, 자신을 인정해주는 환경에 의도적으로 머무르세요.', 80, true),
('element_tag', 'fire_deficient', 'love', '화 부족 · 애정운', '감정 표현이 서툴고 수동적인 경향이 강해집니다. 작은 표현부터 시작하면 관계에 온기가 돌아옵니다.', '화 기운이 부족한 애정운은 감정을 표현하는 데 어려움을 느끼고, 관계에서 주도적으로 나서기보다 기다리는 경향이 강해지는 상태입니다. 상대방에게 마음이 있어도 표현을 미루거나, 관계에서 무기력함을 느끼는 경우가 있을 수 있습니다. 이 시기에는 화려한 표현보다 작고 따뜻한 행동 하나를 먼저 해보세요. 짧은 메시지 한 통, 좋아하는 음식 하나를 챙겨주는 것처럼 작은 관심이 관계에 큰 온기를 불어넣습니다.', 80, true),
('element_tag', 'fire_deficient', 'wealth', '화 부족 · 재물운', '좋은 기회가 와도 결단하지 못해 놓치기 쉬운 시기입니다. 미리 세운 기준에 따라 행동하는 원칙이 도움이 됩니다.', '화 기운이 부족한 재물운은 좋은 투자 기회나 수익 가능성이 눈앞에 있어도 결정을 내리지 못하고 머뭇거리다 타이밍을 놓치는 경향이 있는 상태입니다. 수입은 있어도 재물이 잘 불어나지 않는 느낌이 드는 시기이기도 합니다. 이 시기에는 미리 투자 기준이나 저축 계획을 세워두고, 그 기준에 맞으면 감정과 관계없이 실행하는 규칙을 만드는 것이 효과적입니다. 소액이라도 자동 저축을 시작해 재물을 쌓는 습관을 만들어보세요.', 80, true),
('element_tag', 'fire_deficient', 'health', '화 부족 · 건강운', '혈액순환이 약해지고 추위를 잘 탈 수 있습니다. 몸을 따뜻하게 하고 심장 건강에 신경 쓰는 것이 중요합니다.', '화 기운이 부족하면 심장 기능이 약해지거나 혈액순환이 원활하지 않아 손발이 차가워지고 추위를 심하게 타는 경향이 나타납니다. 또한 무기력함과 함께 소화 기능도 저하될 수 있으니 몸을 따뜻하게 유지하는 것이 중요합니다. 따뜻한 음식과 붉은색 음식(토마토, 석류, 적포도 등)이 화 기운을 보충하는 데 도움이 됩니다. 가벼운 유산소 운동으로 심박수를 올리고 체온을 높이는 루틴을 만들어 꾸준히 이어가세요.', 80, true),
('element_tag', 'earth_excess', 'general', '토 과다 · 총운', '안정과 신뢰를 바탕으로 한 탄탄한 시기입니다. 변화에 좀 더 유연하게 열린 마음을 가지면 더 큰 가능성이 열립니다.', '토(土) 기운이 강한 당신은 안정적이고 신뢰할 수 있으며, 어떤 상황에서도 흔들리지 않는 중심이 있습니다. 주변 사람들에게 든든한 버팀목 역할을 하며, 꾸준함과 성실함으로 오랜 시간에 걸쳐 실력을 쌓는 유형입니다. 그러나 토가 과다하면 변화와 새로운 것에 대한 저항이 커지고, 고집이 지나쳐 기회를 놓치는 경우가 생깁니다. 가끔은 안정을 벗어나 새로운 경험을 의도적으로 만들어보는 것이 성장의 열쇠입니다.', 80, true),
('element_tag', 'earth_excess', 'career', '토 과다 · 직업운', '꼼꼼하고 책임감이 강해 어떤 조직에서도 신뢰받는 존재입니다. 혁신적인 변화를 받아들이는 유연성을 키우는 것이 과제입니다.', '토 기운이 강한 직업운은 관리, 금융, 부동산, 행정 등 꼼꼼함과 지속성이 요구되는 분야에서 빛을 발합니다. 맡은 일을 끝까지 책임지는 성실함과 주변 사람들과 원만한 관계를 유지하는 능력이 뛰어납니다. 그러나 토가 과다하면 변화하는 환경에 적응하는 것이 느리고, 새로운 방식보다 익숙한 방식만을 고집하다가 뒤처지는 경우가 있습니다. 의도적으로 새로운 방법을 시도하고 피드백을 받아들이는 열린 자세가 필요합니다.', 80, true),
('element_tag', 'earth_excess', 'love', '토 과다 · 애정운', '헌신적이고 안정적인 파트너지만, 변화와 새로운 자극이 부족하면 관계가 정체될 수 있습니다. 설렘을 의도적으로 만들어보세요.', '토 기운이 강한 당신은 연애에서 매우 헌신적이고 안정적인 파트너입니다. 상대방을 위해 묵묵히 곁을 지키고, 어려울 때일수록 더 든든한 존재가 됩니다. 그러나 토가 과다하면 관계가 지나치게 안정적인 루틴에 갇혀 설렘이 사라지거나, 변화를 원하는 상대방과 마찰이 생길 수 있습니다. 함께 새로운 장소에 가거나 색다른 경험을 만들어가는 노력이 관계에 활력을 불어넣습니다. 변화를 두려워하지 말고 함께 성장하는 관계를 만들어가세요.', 80, true),
('element_tag', 'earth_excess', 'wealth', '토 과다 · 재물운', '안정적인 자산 축적에 강점이 있습니다. 부동산이나 장기 투자에서 좋은 결과를 기대할 수 있는 시기입니다.', '토 기운이 강한 재물운은 안정적으로 재물을 쌓는 데 탁월한 능력이 있습니다. 충동적인 지출을 잘 억제하고, 꾸준한 저축과 안전한 자산 운용을 통해 장기적으로 재물을 늘려나갑니다. 부동산이나 채권 등 안정적인 자산에서 좋은 결과를 기대할 수 있습니다. 다만 토가 과다하면 지나치게 보수적이어서 좋은 투자 기회를 모두 놓치는 경우가 있으니, 소액으로 새로운 투자를 시험해보는 용기도 필요합니다.', 80, true),
('element_tag', 'earth_excess', 'health', '토 과다 · 건강운', '소화기와 위장 관리가 중요합니다. 과식을 줄이고 규칙적인 식사 습관을 유지하면 건강이 안정됩니다.', '토(土)는 한의학에서 비장(脾)과 위장, 소화기계와 깊이 연결됩니다. 토 기운이 과다하면 소화 기능이 느려지거나 복부 팽만감, 과식 후 불쾌감이 자주 나타날 수 있습니다. 또한 체중이 늘기 쉬운 체질이 되거나 습기에 약해지는 경향이 있습니다. 단맛이 강한 음식을 줄이고 소화에 부담이 적은 음식 위주로 식단을 구성하세요. 식사 후 가벼운 산책을 루틴으로 만들면 소화 기능을 개선하고 토 기운의 과부하를 해소하는 데 효과적입니다.', 80, true),
('element_tag', 'earth_balanced', 'general', '토 균형 · 총운', '안정된 기반 위에 자연스러운 변화가 가능한 균형 잡힌 상태입니다. 지금의 중심을 유지하며 원하는 방향으로 나아가세요.', '토(土) 기운이 균형 잡힌 당신은 안정성과 유연성이 조화를 이루고 있습니다. 흔들리지 않는 중심이 있으면서도 필요한 변화는 받아들일 수 있는 성숙한 상태입니다. 주변 사람들과의 관계가 원만하고, 갈등 상황에서도 중재자 역할을 잘 해낼 수 있습니다. 지금의 이 균형 잡힌 기반 위에서 새로운 도전을 시도해도 좋고, 지금까지 해온 것을 더 깊이 발전시켜도 좋은 시기입니다.', 60, true),
('element_tag', 'earth_balanced', 'career', '토 균형 · 직업운', '실무 능력과 유연성이 균형을 이루는 직업 기질을 타고났습니다. 안정적인 업무 처리와 변화 적응력이 공존해 조직에서 두루 신뢰받는 유형입니다.', '토 기운이 균형을 이룬 직업운은 꼼꼼한 실무 능력과 환경 변화에 적응하는 유연성이 조화로운 상태입니다. 안정적인 업무 처리 능력과 함께 새로운 방식도 열린 마음으로 받아들일 수 있어 조직에서 신뢰와 인정을 동시에 받습니다. 관리직이나 팀 조율 역할에서 특히 빛을 발하며, 동료들에게 신뢰받는 존재가 됩니다. 이 시기에 맡은 역할을 충실히 수행하면서 업무 영역을 조금씩 확장해보는 것을 추천합니다.', 60, true),
('element_tag', 'earth_balanced', 'love', '토 균형 · 애정운', '안정감과 설렘을 균형 있게 추구하는 연애 기질을 가졌습니다. 편안하면서도 함께 성장할 수 있는 관계에서 가장 빛을 발합니다.', '토 기운이 균형 잡힌 애정운은 안정적이면서도 새로운 경험을 함께 만들어가는 건강한 관계가 가능한 상태입니다. 헌신적인 면과 함께 상대방의 필요에 유연하게 반응하는 능력이 있어 관계가 자연스럽게 성숙해집니다. 싱글이라면 자신을 편안하게 해주는 안정적인 인연이 찾아오기 좋은 시기입니다. 현재 관계 중이라면 함께 새로운 경험을 만들어가는 시간을 늘려 관계의 깊이를 더해보세요.', 60, true),
('element_tag', 'earth_balanced', 'wealth', '토 균형 · 재물운', '안정적인 자산 관리와 새로운 기회 탐색의 균형이 잘 맞는 시기입니다. 장기 재무 계획을 세우기 좋은 때입니다.', '토 기운이 균형을 이룬 재물운은 안전한 자산 관리와 새로운 수익 기회 탐색 사이에서 균형 잡힌 접근이 가능한 상태입니다. 충동적인 지출을 잘 통제하면서도 좋은 기회가 왔을 때는 과감하게 행동할 수 있는 판단력이 있습니다. 이 시기에 장기 재무 목표를 구체적으로 세우고 그에 맞는 저축과 투자 계획을 수립하면 몇 년 후 큰 차이를 만들 수 있습니다. 부동산이나 안정적인 금융 상품에 대한 공부를 시작해도 좋습니다.', 60, true),
('element_tag', 'earth_balanced', 'health', '토 균형 · 건강운', '소화기 건강이 안정적인 좋은 상태입니다. 균형 잡힌 식사와 꾸준한 운동을 유지하면 건강한 한 해가 됩니다.', '토 기운이 균형을 이룬 건강운은 소화기, 비장, 위장 등 토와 관련된 신체 기관들이 안정적으로 기능하는 상태입니다. 식욕이 규칙적이고 소화에 큰 문제가 없다면 지금의 식습관을 유지하는 것이 좋습니다. 균형 잡힌 식단, 규칙적인 식사 시간, 과식하지 않는 습관이 이 균형을 지켜줍니다. 가벼운 걷기 운동을 꾸준히 하고, 단 음식 섭취를 적절하게 조절하는 것이 토 기운의 균형 유지에 도움이 됩니다.', 60, true),
('element_tag', 'earth_deficient', 'general', '토 부족 · 총운', '안정적인 중심 잡기가 쉽지 않은 기질로, 일상의 루틴이 특히 중요합니다. 규칙적인 생활 패턴이 이 기질의 가장 강력한 안정제입니다.', '토(土) 기운이 부족한 당신은 안정적인 중심을 잡는 데 어려움을 느끼고, 작은 변화에도 쉽게 흔들리는 경향이 있습니다. 집중력이 떨어지거나 여러 가지에 관심이 분산되어 어느 것 하나 깊이 파고들기 어려운 느낌이 들 수 있습니다. 이 시기에는 일상의 규칙적인 루틴을 만드는 것이 가장 효과적인 대응 방법입니다. 매일 같은 시간에 일어나고, 작은 약속을 지키는 것부터 시작해 내면의 안정감을 쌓아가세요.', 80, true),
('element_tag', 'earth_deficient', 'career', '토 부족 · 직업운', '꼼꼼함과 지속성이 부족해 업무가 흐릿해질 수 있습니다. 체계적인 계획과 확인 루틴이 이 시기의 핵심 전략입니다.', '토 기운이 부족한 직업운은 업무에서 꼼꼼함과 지속성이 약해지기 쉬운 상태입니다. 시작은 잘하지만 마무리가 흐릿해지거나, 업무 계획이 자주 바뀌어 성과가 쌓이지 않는 느낌이 드는 시기입니다. 이 시기에는 체계적인 업무 계획표를 만들고, 매일 완료한 일을 확인하는 루틴을 만드는 것이 큰 도움이 됩니다. 장기 프로젝트보다 단기 완결 업무에 집중하며 작은 성취감을 쌓아가는 것이 좋습니다.', 80, true),
('element_tag', 'earth_deficient', 'love', '토 부족 · 애정운', '관계의 안정성이 부족해 불안감을 느끼기 쉽습니다. 상대방과의 솔직한 소통이 관계의 중심을 잡아줍니다.', '토 기운이 부족한 애정운은 관계에서 안정적인 기반이 약해 사소한 일에도 불안감을 느끼거나 갈등이 잦아질 수 있는 상태입니다. 상대방의 작은 행동을 필요 이상으로 크게 해석하거나, 관계의 미래에 대해 지나치게 걱정하는 경향이 나타날 수 있습니다. 이 시기에는 파트너와 감정을 솔직하게 나누는 대화를 늘리고, 함께 규칙적인 루틴(주말 저녁 식사, 매주 산책 등)을 만들어 관계에 안정적인 패턴을 부여하세요.', 80, true),
('element_tag', 'earth_deficient', 'wealth', '토 부족 · 재물운', '재정 관리가 불안정해지기 쉬운 시기입니다. 자동 저축 시스템을 만들어 규칙적인 재물 관리 습관을 형성하세요.', '토 기운이 부족한 재물운은 재정 관리에서 일관성이 부족해 저축이 잘 안 되거나 계획 없이 지출이 늘어나는 경향이 있는 상태입니다. 수입은 있어도 남는 것이 없는 느낌, 혹은 재정 상황이 자주 들쭉날쭉하는 경험을 할 수 있습니다. 이 시기에는 자동 이체를 통한 강제 저축 시스템을 반드시 만들고, 월별 지출 내역을 기록하는 습관을 들이세요. 재정 목표를 구체적인 숫자로 정하고 시각적으로 확인할 수 있게 만드는 것이 효과적입니다.', 80, true),
('element_tag', 'earth_deficient', 'health', '토 부족 · 건강운', '소화기와 위장이 약해질 수 있습니다. 규칙적인 식사와 위장에 부담을 주지 않는 식단 관리가 중요합니다.', '토 기운이 부족하면 소화 기능이 약해지거나 위장 장애, 식욕 불규칙, 복부 불편감 등이 나타날 수 있습니다. 불규칙한 식사나 과식, 야식이 소화기에 큰 부담을 주는 시기이니 규칙적인 식사 시간을 지키는 것이 중요합니다. 따뜻하고 소화하기 쉬운 음식을 위주로 먹고, 자극적이거나 찬 음식은 줄이세요. 식사 후 바로 눕지 않고 가벼운 산책을 하는 습관이 소화기 건강을 개선하는 데 도움이 됩니다.', 80, true),
('element_tag', 'metal_excess', 'general', '금 과다 · 총운', '강한 의지와 결단력이 있지만 지나친 원칙주의가 관계를 어렵게 만들 수 있습니다. 유연함을 의식적으로 키워보세요.', '금(金) 기운이 강한 당신은 강인한 의지와 명확한 원칙, 날카로운 판단력을 가지고 있습니다. 결단이 필요한 상황에서 흔들리지 않고 올바른 선택을 하는 능력이 뛰어나며, 한번 결심한 것은 반드시 이루고자 하는 강한 추진력이 있습니다. 그러나 금이 과다하면 지나친 완벽주의와 경직된 원칙으로 주변 사람들과 마찰이 생기거나, 유연하게 상황에 대처하는 것이 어려워집니다. 나만의 기준만큼 타인의 다름도 존중하는 유연함이 이 시기의 중요한 성장 포인트입니다.', 80, true),
('element_tag', 'metal_excess', 'career', '금 과다 · 직업운', '전문성과 결단력으로 조직에서 신뢰받는 위치에 오를 수 있습니다. 독단적인 결정보다 협업을 통한 성과가 더 빛납니다.', '금 기운이 강한 직업운은 법률, 의료, 공학, 군사 등 전문성과 원칙이 중요한 분야에서 탁월한 능력을 발휘합니다. 명확한 판단력과 타협 없는 전문성으로 조직에서 없어서는 안 될 존재가 됩니다. 그러나 금이 과다하면 자신의 방식이 가장 옳다는 확신이 지나쳐 독단적으로 행동하거나, 팀원들과의 관계가 경직될 수 있습니다. 자신의 전문성을 유지하면서도 동료의 의견을 경청하고 협력하는 자세를 더하면 성과가 배가됩니다.', 80, true),
('element_tag', 'metal_excess', 'love', '금 과다 · 애정운', '헌신적이고 의리 있는 파트너지만, 감정 표현이 서툴어 오해를 받기 쉽습니다. 마음을 직접 말하는 연습이 필요합니다.', '금 기운이 강한 당신은 연애에서 한번 마음을 주면 끝까지 지키는 의리 있는 파트너입니다. 상대방을 위해 묵묵히 행동으로 보여주는 사랑을 하지만, 감정을 말로 표현하는 것이 서툴러 상대방이 차갑게 느끼는 경우가 있습니다. 금이 과다하면 자신의 기준과 원칙으로 상대방을 판단하거나 통제하려는 경향이 생겨 관계에 갈등이 생길 수 있습니다. 마음속에 있는 것을 말로 표현하는 연습을 하고, 상대방의 방식을 인정하는 유연함을 키워보세요.', 80, true),
('element_tag', 'metal_excess', 'wealth', '금 과다 · 재물운', '절약과 원칙적인 재물 관리가 뛰어납니다. 지나치게 보수적인 자세만 경계하면 재물이 안정적으로 쌓입니다.', '금 기운이 강한 재물운은 충동적인 지출 없이 원칙대로 저축하고 관리하는 능력이 뛰어납니다. 한번 세운 재정 계획은 끝까지 지키는 강한 의지로 장기적으로 안정적인 자산을 쌓아나갑니다. 그러나 금이 과다하면 지나치게 리스크를 기피해 좋은 투자 기회를 놓치거나, 돈을 쓰는 것 자체에 지나친 죄책감을 느끼는 경우도 있습니다. 삶의 질을 높이는 합리적인 지출과 적절한 투자 사이의 균형을 찾아보세요.', 80, true),
('element_tag', 'metal_excess', 'health', '금 과다 · 건강운', '폐와 호흡기, 피부 건강에 특별히 신경 쓰세요. 몸의 긴장을 의식적으로 풀어주는 이완 루틴이 필요합니다.', '금(金)은 한의학에서 폐(肺), 대장, 피부, 호흡기와 깊이 연결됩니다. 금 기운이 과다하면 폐와 호흡기가 예민해져 알레르기, 비염, 천식 증상이 심해지거나 피부 트러블이 나타날 수 있습니다. 또한 몸에 긴장이 쌓이기 쉽고, 완벽주의적 성향으로 인한 만성 스트레스가 면역 기능을 약화시킬 수 있습니다. 깊은 호흡 운동과 명상으로 폐 기능을 강화하고 긴장을 풀어주세요. 매운 음식을 줄이고 하얀색 음식(연근, 배, 무 등)이 폐 건강에 도움이 됩니다.', 80, true),
('element_tag', 'metal_balanced', 'general', '금 균형 · 총운', '원칙과 유연함이 균형을 이루는 기질을 타고났습니다. 중요한 것은 지키되 사소한 것은 넘길 줄 아는 지혜가 대인관계의 강점이 됩니다.', '금(金) 기운이 균형 잡힌 당신은 강한 원칙과 유연한 대처 능력이 조화를 이루고 있습니다. 중요한 것은 지키되 사소한 것은 넘어갈 줄 아는 지혜가 있어 주변 사람들과 원만한 관계를 유지합니다. 결단력이 필요한 순간에는 흔들리지 않고, 협력이 필요한 순간에는 기꺼이 양보하는 균형 잡힌 태도가 신뢰를 쌓게 합니다. 이 균형이 유지되는 지금이 중요한 목표를 향해 나아가기 좋은 시기입니다.', 60, true),
('element_tag', 'metal_balanced', 'career', '금 균형 · 직업운', '전문성과 협력을 동시에 발휘하는 직업 기질을 타고났습니다. 원칙을 지키면서도 팀워크를 해치지 않는 균형이 가장 큰 강점입니다.', '금 기운이 균형을 이룬 직업운은 전문성과 팀워크, 원칙과 유연성이 조화로운 상태입니다. 어떤 업무가 주어져도 자신만의 기준으로 높은 완성도를 추구하면서도 동료들과 협력하는 데 어려움이 없습니다. 이 시기에 맡은 프로젝트에 전문성을 충분히 발휘하면 실력을 인정받고 커리어에서 중요한 발판을 마련할 수 있습니다. 새로운 기술이나 전문 자격을 쌓기 시작하기에도 좋은 타이밍입니다.', 60, true),
('element_tag', 'metal_balanced', 'love', '금 균형 · 애정운', '원칙 있으면서도 따뜻한 감정을 균형 있게 표현하는 성숙한 연애를 하고 있습니다.', '금 기운이 균형 잡힌 애정운은 자신의 가치관을 지키면서도 상대방의 다름을 인정하는 성숙한 관계가 가능한 상태입니다. 의리 있게 곁을 지키는 헌신과 감정을 적절하게 표현하는 따뜻함이 균형을 이루어 상대방에게 믿음직하고 다정한 파트너로 느껴집니다. 싱글이라면 진지하고 건강한 인연을 만나기 좋은 시기입니다. 현재 관계 중이라면 서로에 대한 신뢰와 애정이 더욱 깊어지는 안정적인 흐름이 이어집니다.', 60, true),
('element_tag', 'metal_balanced', 'wealth', '금 균형 · 재물운', '절약과 투자의 균형이 잘 맞아 재물이 꾸준히 쌓이는 시기입니다. 장기 재무 계획이 가장 잘 실현되는 때입니다.', '금 기운이 균형을 이룬 재물운은 저축과 투자, 지출의 균형이 자연스럽게 맞춰지는 상태입니다. 원칙적인 재정 관리 능력과 함께 좋은 기회에 과감하게 투자하는 결단력도 균형 있게 발휘됩니다. 이 시기에 장기 재무 목표를 구체화하고 그에 맞는 투자 포트폴리오를 구성하면 몇 년 후 큰 차이를 만들 수 있습니다. 꾸준히 쌓인 자산이 복리로 성장하는 것을 체감하기 좋은 시기입니다.', 60, true),
('element_tag', 'metal_balanced', 'health', '금 균형 · 건강운', '호흡기와 폐 건강이 안정적인 상태입니다. 꾸준한 유산소 운동과 깊은 호흡 습관으로 이 균형을 유지하세요.', '금 기운이 균형을 이룬 건강운은 폐, 호흡기, 피부 등 금과 관련된 신체 기관들이 안정적으로 기능하는 상태입니다. 호흡이 편안하고 피부 상태도 안정적이라면 지금의 건강 관리 방식이 잘 맞고 있다는 신호입니다. 꾸준한 유산소 운동으로 폐 기능을 강화하고, 깊은 복식 호흡을 일상화하면 이 균형을 더욱 탄탄하게 유지할 수 있습니다. 건조한 계절에는 실내 습도 관리와 충분한 수분 섭취에 신경 써주세요.', 60, true),
('element_tag', 'metal_deficient', 'general', '금 부족 · 총운', '결단력이 상대적으로 약해 기회를 놓치기 쉬운 기질입니다. 작은 선택부터 빠르게 결정하는 연습이 이 기질의 가장 효과적인 성장법입니다.', '금(金) 기운이 부족한 당신은 중요한 결정을 내리거나 단호하게 행동해야 하는 순간에 어려움을 느낍니다. 무언가를 선택해야 할 때 지나치게 많은 것을 고려하다가 결국 아무것도 선택하지 못하거나, 결정 후에도 계속 의심하는 경향이 있습니다. 이 시기에는 완벽한 선택을 추구하기보다 일단 결정하고 수정해나가는 방식을 연습하는 것이 중요합니다. 작은 결정부터 빠르게 내리는 훈련을 통해 선택하는 근육을 키워나가세요.', 80, true),
('element_tag', 'metal_deficient', 'career', '금 부족 · 직업운', '마무리와 결단이 필요한 순간에 어려움을 느낄 수 있습니다. 명확한 목표와 데드라인 설정이 이 시기의 핵심 전략입니다.', '금 기운이 부족한 직업운은 업무에서 결단력과 마무리 능력이 약해지기 쉬운 상태입니다. 프로젝트를 마무리하는 단계에서 더 좋게 만들 수 없을까 하며 계속 수정을 반복하거나, 중요한 제안이나 협상에서 결정을 미루는 경향이 나타날 수 있습니다. 이 시기에는 업무 마감 기한을 명확하게 설정하고 반드시 지키는 습관을 만드세요. 80% 완성도에서 마무리하고 피드백을 통해 개선하는 방식이 효율적입니다.', 80, true),
('element_tag', 'metal_deficient', 'love', '금 부족 · 애정운', '관계에서 결단을 미루는 경향이 강해집니다. 명확한 의사 표현이 관계를 더 건강하게 만들어줍니다.', '금 기운이 부족한 애정운은 관계에서 중요한 결정을 내리는 것을 어려워하는 상태입니다. 고백을 미루거나, 관계의 방향성에 대해 이야기하는 것을 계속 뒤로 미루거나, 갈등 상황에서 해결보다 회피를 선택하는 경향이 나타날 수 있습니다. 이 시기에는 작더라도 명확하게 의사를 표현하는 연습이 필요합니다. 상대방에게 원하는 것, 바라는 것을 솔직하게 말하는 용기가 관계를 더 건강하고 깊게 만들어줍니다.', 80, true),
('element_tag', 'metal_deficient', 'wealth', '금 부족 · 재물운', '투자 결정을 미루다 기회를 놓치기 쉬운 시기입니다. 미리 세운 기준대로 실행하는 원칙 투자가 효과적입니다.', '금 기운이 부족한 재물운은 재정에서 결단력이 약해져 좋은 투자 기회를 눈앞에서 놓치거나, 저축 계획을 세워도 실행하지 못하는 경향이 있는 상태입니다. 너무 많은 정보를 수집하다 오히려 혼란스러워지거나, 마지막 순간에 결정을 번복하는 일이 반복될 수 있습니다. 이 시기에는 미리 간단한 투자 기준을 정하고 그 기준에 맞으면 바로 실행하는 원칙 투자 방식이 효과적입니다. 자동 이체를 활용해 결단 없이도 저축이 이루어지는 시스템을 만드세요.', 80, true),
('element_tag', 'metal_deficient', 'health', '금 부족 · 건강운', '폐와 피부 건강이 약해질 수 있는 시기입니다. 깊은 호흡 운동과 충분한 수분 섭취로 면역력을 높여주세요.', '금 기운이 부족하면 폐 기능이 약해지거나 피부가 건조해지고, 호흡기 감염에 취약해지는 경향이 있습니다. 또한 대장 기능이 약해져 변비나 소화 불량이 나타날 수 있습니다. 면역력이 전반적으로 저하되는 시기이니 충분한 수면과 규칙적인 생활 습관으로 기초 체력을 관리하는 것이 중요합니다. 매일 아침 깊은 복식 호흡 운동을 5분씩 하고, 흰색 음식(배, 무, 연근, 마늘 등)을 꾸준히 섭취하면 금 기운을 보충하는 데 효과적입니다.', 80, true),
('element_tag', 'water_excess', 'general', '수 과다 · 총운', '깊은 지혜와 직관이 넘치는 시기입니다. 지나친 생각이 실행을 막지 않도록, 생각이 70% 익으면 행동으로 옮기는 연습을 하세요.', '수(水) 기운이 강한 당신은 깊은 사고력과 직관력, 뛰어난 감수성을 가지고 있습니다. 상황을 꿰뚫어 보는 지혜와 타인의 마음을 섬세하게 이해하는 공감 능력이 뛰어나며, 복잡한 문제도 본질을 파악하는 능력이 있습니다. 그러나 수가 과다하면 너무 많은 것을 생각하고 분석하다가 정작 행동으로 옮기지 못하거나, 지나친 걱정과 불안이 일상을 무겁게 만드는 경향이 있습니다. 분석이 완벽하지 않아도 행동하면서 배우는 경험이 이 시기에 가장 필요한 성장입니다.', 80, true),
('element_tag', 'water_excess', 'career', '수 과다 · 직업운', '분석력과 전략적 사고가 탁월합니다. 결정을 너무 오래 미루지 않고 적절한 시점에 실행으로 옮기는 것이 성과의 열쇠입니다.', '수 기운이 강한 직업운은 연구, 분석, IT, 전략 기획, 상담 등 깊은 사고와 통찰이 필요한 분야에서 빛을 발합니다. 남들이 보지 못하는 패턴을 발견하고, 복잡한 정보를 체계적으로 분석하는 능력이 뛰어납니다. 그러나 수가 과다하면 더 좋은 방법을 찾는 데 너무 많은 시간을 쓰다가 결정을 미루거나, 완벽한 계획이 세워질 때까지 실행을 시작하지 않는 경향이 생깁니다. 80% 준비가 됐다고 느끼면 실행하는 용기를 연습하세요.', 80, true),
('element_tag', 'water_excess', 'love', '수 과다 · 애정운', '감수성이 풍부하고 깊은 사랑을 하지만, 지나친 감정 몰입이 관계를 힘들게 만들 수 있습니다. 자신만의 공간도 소중히 하세요.', '수 기운이 강한 당신의 사랑은 깊고 진합니다. 상대방의 감정을 섬세하게 읽고 공감하는 능력이 뛰어나며, 관계에 깊이 헌신하는 성향이 있습니다. 그러나 수가 과다하면 상대방의 감정에 지나치게 몰입하거나, 작은 신호에도 과도하게 의미를 부여해 혼자 걱정하고 상처받는 경우가 생깁니다. 상대방을 사랑하는 것만큼 자신을 돌보는 것도 중요합니다. 혼자만의 시간과 공간을 의도적으로 만들어 감정의 균형을 유지하세요.', 80, true),
('element_tag', 'water_excess', 'wealth', '수 과다 · 재물운', '기회를 예민하게 포착하는 능력이 있습니다. 지나친 걱정으로 결정을 미루지 않도록 미리 판단 기준을 만들어두세요.', '수 기운이 강한 재물운은 시장의 흐름을 읽고 기회를 직관적으로 포착하는 능력이 뛰어납니다. 다른 사람들이 눈치채지 못하는 투자 기회를 미리 발견하거나, 재정 위기를 사전에 감지하는 감각이 있습니다. 그러나 수가 과다하면 분석을 무한 반복하다 좋은 기회를 놓치거나, 손실에 대한 걱정이 지나쳐 아무것도 실행하지 못하는 경우가 생깁니다. 투자 기준을 미리 명확하게 세우고 그 기준에 맞으면 두려움 없이 실행하는 연습이 필요합니다.', 80, true),
('element_tag', 'water_excess', 'health', '수 과다 · 건강운', '신장과 방광 건강을 주의 깊게 관리하세요. 몸을 따뜻하게 유지하고 충분한 휴식으로 신체 에너지를 보충해야 합니다.', '수(水)는 한의학에서 신장(腎), 방광, 골격, 호르몬계와 깊이 연결됩니다. 수 기운이 과다하면 신장과 방광에 부담이 가거나, 부종, 냉증, 허리와 무릎 통증이 나타날 수 있습니다. 또한 지나친 생각과 걱정으로 수면의 질이 떨어지거나, 호르몬 불균형이 나타날 수 있습니다. 몸을 따뜻하게 유지하고 찬 음식과 찬 음료를 줄이는 것이 중요합니다. 짠맛보다 검은색 음식(검은콩, 흑미, 블루베리 등)과 충분한 수분 섭취가 신장 건강에 도움이 됩니다.', 80, true),
('element_tag', 'water_balanced', 'general', '수 균형 · 총운', '지혜와 실행력이 균형을 이루는 기질을 타고났습니다. 충분히 생각한 후 적절한 타이밍에 행동으로 옮기는 능력이 삶 전반에서 강점이 됩니다.', '수(水) 기운이 균형 잡힌 당신은 깊은 사고력과 실행 능력이 조화를 이루고 있습니다. 충분히 생각하고 분석한 후 적절한 타이밍에 행동으로 옮기는 능력이 있어, 중요한 결정에서 좋은 결과를 만들어냅니다. 직관이 발달해 있으면서도 지나친 걱정에 빠지지 않는 균형 잡힌 상태가 삶의 여러 영역에서 좋은 결과를 가져옵니다. 지금의 이 흐름을 믿고 하고 싶었던 일에 도전해보세요.', 60, true),
('element_tag', 'water_balanced', 'career', '수 균형 · 직업운', '분석력과 실행력이 자연스럽게 조화를 이루는 직업 기질입니다. 깊이 생각하면서도 적절한 타이밍에 행동할 줄 아는 것이 핵심 강점입니다.', '수 기운이 균형을 이룬 직업운은 깊은 분석력과 전략적 사고를 바탕으로 실행까지 이어지는 이상적인 상태입니다. 복잡한 문제를 꿰뚫어 보는 통찰력과 그것을 실제 결과로 만들어내는 능력이 동시에 발휘되어 어떤 분야에서도 인정받을 수 있습니다. 중요한 전략적 결정이나 새로운 프로젝트를 시작하기에 좋은 타이밍입니다. 자신의 직관을 믿고 행동하면 생각보다 훨씬 좋은 결과가 따라옵니다.', 60, true),
('element_tag', 'water_balanced', 'love', '수 균형 · 애정운', '감성과 이성이 균형을 이루는 성숙한 관계를 이어가고 있습니다. 서로를 깊이 이해하는 의미 있는 시간이 됩니다.', '수 기운이 균형 잡힌 애정운은 감성적인 공감 능력과 이성적인 판단력이 조화를 이루는 성숙한 사랑이 가능한 상태입니다. 상대방의 감정을 섬세하게 읽으면서도 자신의 감정에 지나치게 휩쓸리지 않는 균형이 건강한 관계를 만듭니다. 싱글이라면 진정한 내면의 연결이 가능한 깊이 있는 인연을 만날 준비가 된 시기입니다. 현재 관계 중이라면 서로에 대한 이해가 한층 더 깊어지는 의미 있는 시간이 이어집니다.', 60, true),
('element_tag', 'water_balanced', 'wealth', '수 균형 · 재물운', '기회를 현명하게 포착하고 안정적으로 관리하는 재물 흐름입니다. 장기적인 재무 전략을 세우기 가장 좋은 시기입니다.', '수 기운이 균형을 이룬 재물운은 시장의 흐름을 읽는 직관과 신중하게 판단하는 이성이 함께 작동하는 이상적인 상태입니다. 좋은 기회를 포착하는 감각이 있으면서도 지나친 위험은 피하는 균형 잡힌 판단이 가능합니다. 이 시기에 장기적인 재무 전략을 세우고 그에 맞는 투자 포트폴리오를 구성하면 수년 후 큰 차이를 만들 수 있습니다. 지금의 재정 상황을 객관적으로 분석하고 다음 단계의 목표를 설정해보세요.', 60, true),
('element_tag', 'water_balanced', 'health', '수 균형 · 건강운', '신장과 방광 기능이 안정적인 좋은 상태입니다. 충분한 수분 섭취와 적절한 운동으로 이 균형을 유지하세요.', '수 기운이 균형을 이룬 건강운은 신장, 방광, 골격 등 수와 관련된 신체 기관들이 안정적으로 기능하는 상태입니다. 수분 균형이 잘 유지되고 있으며 호르몬 기능도 안정적입니다. 매일 충분한 물을 마시고, 규칙적인 운동으로 신진대사를 원활하게 유지하는 것이 지금의 균형을 지켜주는 핵심입니다. 특히 허리와 무릎을 과도하게 사용하지 않도록 주의하고, 적절한 스트레칭으로 관절 건강을 관리해주세요.', 60, true),
('element_tag', 'water_deficient', 'general', '수 부족 · 총운', '직관력과 유연한 사고가 상대적으로 약한 기질입니다. 시야를 넓히는 다양한 경험과 독서가 이 기질의 가장 좋은 보완책입니다.', '수(水) 기운이 부족한 당신은 직관력과 유연한 사고가 약해지는 시기에 있습니다. 변화하는 상황에 유연하게 적응하기보다 정해진 방식만을 고집하거나, 상황의 큰 흐름을 파악하는 것이 어렵게 느껴질 수 있습니다. 이 시기에는 다양한 책을 읽거나 새로운 환경에 자신을 노출시켜 시야를 넓히는 것이 효과적입니다. 혼자 모든 것을 판단하려 하기보다 경험이 풍부한 사람들의 의견을 경청하고 받아들이는 열린 자세를 키워나가세요.', 80, true),
('element_tag', 'water_deficient', 'career', '수 부족 · 직업운', '전략적 사고와 분석력 보완이 필요한 시기입니다. 세부 업무에 집중하며 꾸준히 역량을 쌓아가는 것이 현명합니다.', '수 기운이 부족한 직업운은 전략적 사고와 큰 그림을 보는 분석력이 약해지는 상태입니다. 눈앞의 일은 잘 처리하지만 장기적인 방향이나 업무의 맥락을 파악하는 것이 어렵게 느껴질 수 있습니다. 이 시기에는 전략적 판단이 필요한 역할보다 명확한 목표가 주어진 실무 중심 업무에 집중하는 것이 효율적입니다. 업계 트렌드를 파악하는 공부를 꾸준히 하고, 멘토나 선배의 경험을 적극적으로 배우는 자세를 취하세요.', 80, true),
('element_tag', 'water_deficient', 'love', '수 부족 · 애정운', '상대방의 감정을 깊이 이해하는 공감 능력이 약해질 수 있습니다. 귀를 더 기울이고 대화를 늘리는 것이 관계의 깊이를 더해줍니다.', '수 기운이 부족한 애정운은 상대방의 감정을 섬세하게 읽고 공감하는 능력이 약해지는 상태입니다. 상대방이 표현하지 않아도 마음을 알아채는 섬세함이 부족해져, 오해나 소통의 단절이 생기기 쉬운 시기입니다. 이 시기에는 바쁘더라도 대화하는 시간을 의도적으로 늘리고, 상대방이 하는 말을 끝까지 들어주는 연습을 하세요. 직접 물어보고 확인하는 솔직한 소통이 오해를 예방하고 관계를 더 깊게 만들어줍니다.', 80, true),
('element_tag', 'water_deficient', 'wealth', '수 부족 · 재물운', '시장의 큰 흐름을 읽는 감각이 약한 시기입니다. 전문가 조언을 적극 활용하고 안정적인 자산 관리에 집중하세요.', '수 기운이 부족한 재물운은 시장의 흐름이나 투자 기회를 직관적으로 포착하는 감각이 약해지는 상태입니다. 좋은 기회가 있어도 그것의 의미를 제때 파악하지 못하거나, 재정 계획의 큰 방향을 설정하는 데 어려움을 느낄 수 있습니다. 이 시기에는 전문 재정 상담사나 경험 있는 투자자의 조언을 적극 활용하고, 스스로 판단해야 하는 복잡한 투자보다 안정적이고 검증된 금융 상품 위주로 관리하는 것이 현명합니다.', 80, true),
('element_tag', 'water_deficient', 'health', '수 부족 · 건강운', '신장과 방광, 뼈 건강에 주의가 필요합니다. 충분한 수분 섭취와 보온에 신경 쓰고 무리한 활동을 줄이세요.', '수 기운이 부족하면 신장 기능이 약해지거나 허리, 무릎 통증, 탈모, 청력 저하 등이 나타날 수 있습니다. 또한 체내 수분이 부족해지고 호르몬 균형이 흐트러지거나, 쉽게 피로를 느끼는 경향이 있습니다. 하루 충분한 양의 물을 마시고, 찬 기운에 노출되는 것을 최소화하며 몸을 따뜻하게 유지하세요. 검은콩, 검은깨, 굴 등 검은색 음식과 해산물이 신장 기운을 보충하는 데 도움이 됩니다. 무리한 운동보다 가벼운 수영이나 걷기 운동을 꾸준히 하세요.', 80, true)
